{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "notebook edición video 4K alto rendimiento",
        "category": "notebooks",
        "attributes": {"ram_gb": {"min": 32}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id", "$s1.2.id"]
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "$s2.mejor_evaluado",
        "limit": 5
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "¡Hola! Para edición de video 4K necesitas músculo de verdad, y encontré opciones con 32 GB de RAM o más. Tras comparar las alternativas disponibles, el mejor evaluado por otros usuarios es **{nombre_top}** <<rec:{id_top}>> a ${precio_top} CLP. Lo que dicen quienes lo han usado: {resumen_reviews}. También puedes considerar **{nombre2}** <<rec:{id2}>> (${precio2} CLP) y **{nombre3}** <<rec:{id3}>> (${precio3} CLP). Si quieres ver cómo se comparan entre sí: <<cmp:{id_top},{id2}>> <<cmp:{id_top},{id3}>>. ¿Te gustaría más detalles de alguno?",
      "vars": {
        "nombre_top": "$s2.mejor_evaluado",
        "id_top": "$s2.mejor_evaluado",
        "precio_top": "$s1.0.price_clp",
        "resumen_reviews": "$s3",
        "nombre2": "$s1.1.name",
        "id2": "$s1.1.id",
        "precio2": "$s1.1.price_clp",
        "nombre3": "$s1.2.name",
        "id3": "$s1.2.id",
        "precio3": "$s1.2.price_clp"
      }
    }
  ]
}
